using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class DeadmansLane : LayoutBase
{
    public DeadmansLane()
    {
        Name = LayoutNamesEnums.DeadmansLane;
        Owner = "Andy Bryan and Peter Taylor";
        Description = "A depiction of the Deadman's Lane site in Derby, where the East Midlands Trains Etches Park depot sits across the Derby to Long Eaton main line from the yellow of Network Rail's test fleet, based at the former British Rail Research and Technical Centre and now largely occupied by Loram. Very much compressed to fit the available space, it portrays the workings of a busy depot and the adjacent main line over the past three or four years, with guest appearances by former residents of the RTC site. Most of the yellow stock is converted from ready-to-run items to represent test coaches such as the Electrification Measurement Vehicle and the Structure Gauging Train - unusually the layout was built to suit a collection that had already grown, rather than the other way round. It is DCC controlled via a Lenz system with the majority of powered vehicles sound fitted, usually with ESU LokSound decoders, while point control in the scenic section uses an independent DCC system with DCCconcepts Alpha Switch and encoders and a Megapoints servo controller and route setting card looks after the storage yard.";
    }
}
